import numpy as np

def problem(x: np.ndarray) -> float:
    n = len(x)
    if n != 5:
        raise ValueError("Dimension must be 5")

    x = np.clip(x, -5, 5)
    sigmoid = 1 / (1 + np.exp(-x))
    fitness = 0.4 * np.sum(x**2) + 0.15 * np.sum(x * np.roll(x, 1)) + 0.45 * np.sum(np.exp(x) * sigmoid) + 0.01*x[0]
    return float(fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    n = len(x)
    if n != 5:
        raise ValueError("Dimension must be 5")

    x = np.clip(x, -5, 5)
    sigmoid = 1 / (1 + np.exp(-x))
    fitness = 0.5 * np.sum(x**2) + 0.3 * np.sum(np.exp(x) * sigmoid)  + 0.02*x[0]
    return float(fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    n = len(x)
    if n != 5:
        raise ValueError("Dimension must be 5")

    x = np.clip(x, -5, 5)
    sigmoid = 1 / (1 + np.exp(-x))
    fitness = 0.4 * np.sum(x**2) + 0.15 * np.sum(x * np.roll(x, 1)) + 0.4 * np.sum(np.exp(x) * sigmoid) + 0.03 * np.sum(np.abs(x)**0.6)
    return float(fitness)
